mapper.insert:
INSERT INTO family (
user_id, family_name_encrypted, relation, birth_date_encrypted, family_img
) VALUES (
#{userId}, #{familyNameEncrypted}, #{relation}, #{birthDateEncrypted}, #{familyImg}
)

mapper.update:
UPDATE family
SET family_name_encrypted = #{familyNameEncrypted},
relation = #{relation},
birth_date_encrypted = #{birthDateEncrypted},
family_img = #{familyImg}
WHERE family_id = #{familyId}
AND user_id = #{userId}

mapper.delete:
DELETE FROM family
WHERE family_id = #{familyId}
AND user_id = #{userId}

mapper.select:
SELECT

FROM family
WHERE family_id = #{familyId} AND user_id = #{userId}
